  function iuDbgSelectPre(preEl){
    try{
      if (!preEl) return;
      const sel = window.getSelection ? window.getSelection() : null;
      if (!sel || !document.createRange) return;
      const range = document.createRange();
      range.selectNodeContents(preEl);
      sel.removeAllRanges();
      sel.addRange(range);
    }catch{}
  }

