  function normalizeMediaName(name) {
    if (!name || typeof name !== "string") return "";
    const normalized = name.toLowerCase().trim();
    
    // Mapování variant názvů médií na canonical tvar
    const mediaMap = {
      "česká televize": "ct24",
      "ceska televize": "ct24",
      "ct24": "ct24",
      "irozhlas": "irozhlas",
      "irozhlas.cz": "irozhlas",
      "irozhlas sport": "irozhlas-sport",
      "idnes": "idnes",
      "idnes.cz": "idnes",
      "seznam zpravy": "seznamzpravy",
      "seznam zprávy": "seznamzpravy",
      "seznamzpravy": "seznamzpravy",
    };
    
    return mediaMap[normalized] || normalized;
  }

  const IU_TIMELINE_SECTION_COLORS = Object.freeze({
    zpravy: "#EF4444",
    aktualne: "#EF4444",
    sport: "#22C55E",
    finance: "#C9A24D",
    zdravi: "#2DB8A8",
    cestovani: "#E8892E",
    hry: "#8B6FD4",
    kultura: "#F06BA8",
    "kultura-akce": "#F06BA8",
    veda: "#5B9FE8",
    "veda-historie": "#5B9FE8",
    vzdelavani: "#E6C200",
    "prehled-dne": "#EF4444",
    hub: "#EF4444",
  });

  function iuTimelineResolveSectionKey(it) {
    const raw = String(it?.section || it?.topic || "").trim().toLowerCase();
    if (raw === "aktualne") return "zpravy";
    if (raw === "kultura-akce" || raw === "kultura_akce") return "kultura";
    if (raw === "veda-historie" || raw === "veda_historie") return "veda";
    if (raw === "prehled-dne" || raw === "prehled_dne") return "prehled-dne";
    return raw || "zpravy";
  }

  function iuTimelineSectionDotColor(it) {
    const key = iuTimelineResolveSectionKey(it);
    return IU_TIMELINE_SECTION_COLORS[key] || IU_TIMELINE_SECTION_COLORS.zpravy;
  }

  function iuTimelineClockTime(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return "";
    return d.toLocaleTimeString("cs-CZ", { hour: "2-digit", minute: "2-digit" });
  }

  function iuTimelineRelativeFreshness(it) {
    const ms = iuNewsPreviewParsePublishedMs(it);
    const rel = iuCsRelativeFreshnessFromMs(ms);
    return rel ? String(rel).replace(/\.$/, "") : "";
  }

  function iuTimelineLeftBlock(it) {
    const iso = iuArticleUserVisibleTimeIso(it);
    const clock = iuTimelineClockTime(iso);
    const rel = iuTimelineRelativeFreshness(it);
    const clockPart = clock ? `<span class="iuTimelineClock">${escapeHtml(clock)}</span>` : "";
    const relPart = rel ? `<span class="iuTimelineRelative">${escapeHtml(rel)}</span>` : "";
    return clockPart + relPart;
  }

  function iuTimelineSourceMetaLine(it, fallbackLabel) {
    const srcRaw = Array.isArray(it?.sources) ? it.sources : [];
    const seen = new Set();
    const src = [];
    for (const s of srcRaw) {
      const name = (s?.name || "").trim();
      const url = (s?.url || "").trim();
      if (!name || !url) continue;
      if (iuIsHardBlockedArticleUrl(url)) continue;
      if (iuIsHardBlockedSourceLabel(name)) continue;
      const urlBase = url.split("?")[0].split("#")[0].toLowerCase();
      const canonicalName = normalizeMediaName(name);
      const key = `${urlBase}||${canonicalName}`;
      if (seen.has(key)) continue;
      seen.add(key);
      src.push({ name, url });
    }
    let displayName = String(fallbackLabel || "").trim();
    if (src.length) {
      const primary = src[0];
      const labelFromArticle = String(it?.sourceLabel || "").trim();
      const primaryNameRaw = String(primary.name || "").trim();
      displayName = labelFromArticle || primaryNameRaw || displayName;
      const primaryUrlRaw = normalizeArticleUrl(primary.url) || primary.url;
      const primaryUrl = safeUrl(primaryUrlRaw);
      if (primaryUrl) {
        return `<div class="iu-meta-line"><span class="iu-meta-src">Zdroj: <a class="iu-meta-link" href="${escapeHtml(primaryUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(displayName)}</a></span></div>`;
      }
      return `<div class="iu-meta-line"><span class="iu-meta-src">Zdroj: ${escapeHtml(displayName)}</span></div>`;
    }
    if (!displayName) return "";
    return `<div class="iu-meta-line"><span class="iu-meta-src">Zdroj: ${escapeHtml(displayName)}</span></div>`;
  }

  const IU_BRAND_BLUE = "#003CFF";
  const IU_ARTICLE_ACTION_SAVE_COLOR = "#F59E0B";
  const IU_ARTICLE_ACTION_FOLLOW_COLOR = "#003CFF";
  const IU_ARTICLE_ACTION_HIDE_COLOR = "#DC2626";
  const IU_SAVED_ARTICLES_KEY = "iuSavedArticles";
  const IU_FOLLOWED_TOPICS_KEY = "iuFollowedTopics";
  const IU_HIDDEN_ARTICLES_KEY = "iuHiddenArticles";
  const IU_READ_ARTICLES_KEY = "iuReadArticles_v1";
  const IU_READ_ARTICLES_MAX = 2500;
  const IU_HIDE_UNDO_MS = 5000;

  function iuTimelineCompactViewportMatches() {
    try {
      return !!(window.matchMedia && window.matchMedia("(max-width: 1024px)").matches);
    } catch (_) {}
    return false;
  }

  let iuTimelineAxisResizeBound = false;
  let iuTimelineAxisRo = null;
  let iuTimelineAxisRoRaf = 0;

  function iuTimelineAxisBottomOffset(art, axisTop) {
    let bottom = 0;
    const meta = art.querySelector(
      ".iuTimelineRight .iu-meta-line, .iuTimelineRight .iuTimelineYouTubeMeta"
    );
    if (meta) {
      const metaBottom = meta.getBoundingClientRect().bottom - axisTop;
      if (metaBottom > bottom) bottom = metaBottom;
    }
    if (bottom <= 0) {
      const anchor = art.querySelector(
        ".iuTimelineRight .news-title, .iuTimelineRight .news-titleLink"
      );
      if (anchor) bottom = anchor.getBoundingClientRect().bottom - axisTop;
    }
    if (bottom <= 0) {
      const dot = art.querySelector(".iuTimelineDot");
      if (dot) bottom = dot.getBoundingClientRect().bottom - axisTop;
    }
    return bottom;
  }

  function iuTimelineSyncCompactAxisHeights(feedRoot) {
    try {
      if (!IU_TIMELINE_ENABLED) return;
      const root =
        feedRoot && typeof feedRoot.querySelectorAll === "function"
          ? feedRoot
          : document.getElementById("feed");
      if (!root || !root.classList || !root.classList.contains("iuTimelineFeed")) return;
      const items = root.querySelectorAll(
        "article.iuTimelineItem[data-feed-type='article'], article.iuTimelineItem.iuTimelineItem--video"
      );
      const compact = iuTimelineCompactViewportMatches();
      for (const art of items) {
        const axis = art.querySelector(".iuTimelineAxis");
        if (!axis) continue;
        const axisTop = axis.getBoundingClientRect().top;
        const axisH = Math.ceil(iuTimelineAxisBottomOffset(art, axisTop));
        if (axisH > 0) {
          const next = axisH + "px";
          if (String(axis.style.getPropertyValue("--iu-tl-axis-h") || "").trim() === next) continue;
          axis.style.setProperty("--iu-tl-axis-h", next);
        } else if (axis.style.getPropertyValue("--iu-tl-axis-h")) {
          axis.style.removeProperty("--iu-tl-axis-h");
        }
      }
    } catch (_) {}
  }

  function iuTimelineEnsureCompactAxisObserver(feedRoot) {
    try {
      if (!IU_TIMELINE_ENABLED) return;
      const root = feedRoot || document.getElementById("feed");
      if (!root) return;
      if (!iuTimelineAxisResizeBound) {
        iuTimelineAxisResizeBound = true;
        window.addEventListener(
          "resize",
          function () {
            iuTimelineSyncCompactAxisHeights(document.getElementById("feed"));
          },
          { passive: true }
        );
      }
      if (typeof ResizeObserver !== "undefined") {
        if (!iuTimelineAxisRo) {
          iuTimelineAxisRo = new ResizeObserver(function () {
            if (iuTimelineAxisRoRaf) cancelAnimationFrame(iuTimelineAxisRoRaf);
            iuTimelineAxisRoRaf = requestAnimationFrame(function () {
              iuTimelineAxisRoRaf = 0;
              iuTimelineSyncCompactAxisHeights(document.getElementById("feed"));
            });
          });
        }
        iuTimelineAxisRo.disconnect();
        iuTimelineAxisRo.observe(root);
      }
      iuTimelineSyncCompactAxisHeights(root);
      requestAnimationFrame(function () {
        iuTimelineSyncCompactAxisHeights(root);
      });
    } catch (_) {}
  }

  function iuReadArticlesGetIdSet() {
    try {
      if (window.__iuReadArticlesMemSet instanceof Set) return window.__iuReadArticlesMemSet;
    } catch (_) {}
    const set = new Set();
    const list = iuArticleActionsReadJson(IU_READ_ARTICLES_KEY);
    for (const row of list) {
      const id = String(row || "").trim();
      if (id) set.add(id);
    }
    try {
      window.__iuReadArticlesMemSet = set;
    } catch (_) {}
    return set;
  }

  function iuReadArticlesPersistSet(set) {
    const arr = Array.from(set || []);
    const payload =
      arr.length > IU_READ_ARTICLES_MAX ? arr.slice(arr.length - IU_READ_ARTICLES_MAX) : arr;
    try {
      window.__iuReadArticlesMemSet = set instanceof Set ? set : new Set(payload);
    } catch (_) {}
    try {
      localStorage.setItem(IU_READ_ARTICLES_KEY, JSON.stringify(payload));
      return true;
    } catch (_) {
      return false;
    }
  }

  function iuReadArticlesIsRead(articleId) {
    const id = String(articleId || "").trim();
    if (!id) return false;
    return iuReadArticlesGetIdSet().has(id);
  }

  function iuReadArticlesMarkRead(articleId, articleEl) {
    const id = String(articleId || "").trim();
    if (!id) return;
    const set = iuReadArticlesGetIdSet();
    if (!set.has(id)) {
      set.add(id);
      iuReadArticlesPersistSet(set);
    }
    if (articleEl) iuReadArticlesApplyToArticle(articleEl, true);
  }

  function iuReadArticlesApplyToArticle(articleEl, knownRead) {
    if (!articleEl) return;
    const id = String(articleEl.getAttribute("data-iu-article-id") || "").trim();
    const isRead = knownRead === true ? true : !!(id && iuReadArticlesIsRead(id));
    articleEl.classList.toggle("iuTimelineItem--read", !!isRead);
    const left = articleEl.querySelector(".iuTimelineLeft");
    if (!left) return;
    let mark = left.querySelector(".iuTimelineReadMark");
    if (isRead) {
      if (!mark) {
        mark = document.createElement("span");
        mark.className = "iuTimelineReadMark";
        mark.setAttribute("aria-hidden", "true");
        mark.textContent = "✓";
        left.appendChild(mark);
      }
    } else if (mark) {
      mark.remove();
    }
  }

  function iuReadArticlesSyncFeed(feedRoot) {
    try {
      if (!feedRoot) return;
      feedRoot.querySelectorAll("article.iuTimelineItem[data-feed-type='article']").forEach(function (art) {
        iuReadArticlesApplyToArticle(art);
      });
    } catch (_) {}
  }

  function iuArticleActionsReadJson(key) {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
      return [];
    }
  }

  function iuArticleActionsWriteJson(key, list) {
    if (!isLocalDataProtectionNoticeAccepted()) {
      void ensureLocalDataProtectionBeforeSave().then(function (ok) {
        if (!ok) return;
        try {
          localStorage.setItem(key, JSON.stringify(Array.isArray(list) ? list : []));
          iuArticleActionsOnStoreChanged(key);
        } catch (_) {}
      });
      return false;
    }
    try {
      localStorage.setItem(key, JSON.stringify(Array.isArray(list) ? list : []));
      iuArticleActionsOnStoreChanged(key);
      return true;
    } catch (_) {
      return false;
    }
  }

  function iuArticleActionsOnStoreChanged(key) {
    try {
      const k = String(key || "");
      if (
        k !== IU_SAVED_ARTICLES_KEY &&
        k !== IU_HIDDEN_ARTICLES_KEY &&
        k !== IU_FOLLOWED_TOPICS_KEY
      ) {
        return;
      }
      iuArticleActionsRefreshManagePanels();
      if (k === IU_HIDDEN_ARTICLES_KEY) {
        try {
          if (typeof applyFilter === "function") applyFilter({ resetPage: false, render: true });
        } catch (_) {}
      }
    } catch (_) {}
  }

  function iuArticleActionsResolveId(it) {
    return iuLoadMorePinKey(it) || "";
  }

  function iuArticleActionsResolveSource(it) {
    try {
      const srcRaw = Array.isArray(it?.sources) ? it.sources : [];
      for (const s of srcRaw) {
        const name = String(s?.name || "").trim();
        if (name) return name;
      }
      const label = String(it?.sourceLabel || "").trim();
      if (label) return label;
    } catch (_) {}
    return "";
  }

  function iuArticleActionsResolveTopic(it) {
    try {
      const topic = String(it?.topic || "").trim();
      if (topic) return topic;
      const category = String(it?.category || "").trim();
      if (category) return category;
      const section = String(it?.section || "").trim();
      if (section) return section;
      const tags = Array.isArray(it?.tags) ? it.tags : [];
      for (const tag of tags) {
        const t = String(tag || "").trim();
        if (t) return t;
      }
      return iuTimelineResolveSectionKey(it);
    } catch (_) {
      return "zpravy";
    }
  }

  function iuArticleActionsSnapshot(it) {
    const id = iuArticleActionsResolveId(it);
    if (!id) return null;
    const iso = iuArticleUserVisibleTimeIso(it);
    return {
      articleId: id,
      title: safeText(it?.title || it?.name || "(bez názvu)"),
      source: iuArticleActionsResolveSource(it),
      url: id,
      timestamp: iso || new Date().toISOString(),
      section: iuTimelineResolveSectionKey(it),
      topic: iuArticleActionsResolveTopic(it),
    };
  }

  function iuArticleActionsGetSavedList() {
    return iuArticleActionsReadJson(IU_SAVED_ARTICLES_KEY);
  }

  function iuArticleActionsGetFollowedList() {
    return iuArticleActionsReadJson(IU_FOLLOWED_TOPICS_KEY).filter((row) => {
      const id = String(row?.articleId || row?.url || "").trim();
      return !!id;
    });
  }

  function iuArticleActionsGetHiddenList() {
    return iuArticleActionsReadJson(IU_HIDDEN_ARTICLES_KEY);
  }

  function iuArticleActionsGetHiddenSet() {
    const set = new Set();
    for (const row of iuArticleActionsGetHiddenList()) {
      const id = String(row?.articleId || row?.url || "").trim();
      if (id) set.add(id);
    }
    return set;
  }

  function iuArticleActionsIsSaved(id) {
    const key = String(id || "").trim();
    if (!key) return false;
    return iuArticleActionsGetSavedList().some((row) => String(row?.articleId || row?.url || "").trim() === key);
  }

  function iuArticleActionsIsFollowed(id) {
    const key = String(id || "").trim();
    if (!key) return false;
    return iuArticleActionsGetFollowedList().some(
      (row) => String(row?.articleId || row?.url || "").trim() === key
    );
  }

  function iuArticleActionsFilterVisible(items) {
    try {
      const hidden = iuArticleActionsGetHiddenSet();
      if (!hidden.size) return items;
      return items.filter((it) => {
        if (String(it?.contentType || "").toLowerCase() !== "article") return true;
        const id = iuArticleActionsResolveId(it);
        return !id || !hidden.has(id);
      });
    } catch (_) {
      return items;
    }
  }

