  const IU_HOME_CARDS_ORDER_KEY = "iu_desktop_homecards_order_v1";
  const IU_HOME_CARDS_ORDER_DEFAULT = Object.freeze([
    "zpravy",
    "sport",
    "finance",
    "zdravi",
    "cestovani",
    "hry",
    "kultura",
    "veda",
    "vzdelavani",
    "prehled-dne",
  ]);
  const IU_HOME_CARD_MOUNT_BY_KEY = Object.freeze({
    "zpravy": "iuNewsPreviewCardMount",
    "sport": "iuSportPreviewCardMount",
    "finance": "iuFinancePreviewCardMount",
    "zdravi": "iuHealthPreviewCardMount",
    "cestovani": "iuTravelPreviewCardMount",
    "hry": "iuGamesPreviewCardMount",
    "kultura": "iuCulturePreviewCardMount",
    "veda": "iuScienceHistoryPreviewCardMount",
    "vzdelavani": "iuEducationPreviewCardMount",
    "prehled-dne": "iuPrehledDnePreviewCardMount",
  });

  /** Production cutover: legacy HomeCards must not exist. off/parallel may inject them. */
  function iuLegacyHomeCardsWanted() {
    try {
      const q = new URLSearchParams(location.search || "");
      const mode = String(q.get("iuInfoSystem") || "").toLowerCase();
      if (mode === "parallel" || mode === "off") return true;
      if (mode === "cutover" || mode === "1" || mode === "on") return false;
    } catch (_) {}
    try {
      if (typeof window !== "undefined" && window.__IU_INFO_SYSTEM_CUTOVER__ === false) return true;
      if (typeof window !== "undefined" && window.__IU_INFO_SYSTEM_CUTOVER__ === true) return false;
    } catch (_) {}
    try {
      if (document.documentElement.classList.contains("iu-info-system-parallel")) return true;
      if (document.documentElement.classList.contains("iu-info-system-cutover")) return false;
    } catch (_) {}
    return false;
  }

  function iuLegacyHomeCardsEnsureShell() {
    try {
      if (!iuLegacyHomeCardsWanted()) return;
      const viewport = document.getElementById("iuSilverTallScrollViewport");
      if (!viewport) return;
      const tall = document.getElementById("iuSilverTallScrollSection");
      const welcome = document.getElementById("iuSilverWelcomeStack");
      if (tall && welcome && !document.getElementById("iuFeedNewsSplit")) {
        const split = document.createElement("div");
        split.id = "iuFeedNewsSplit";
        split.className = "iuFeedNewsSplit";
        split.setAttribute("aria-hidden", "true");
        split.innerHTML =
          '<div class="iuFeedNewsSplit__row">' +
          '<span class="iuFeedNewsSplit__line" aria-hidden="true"></span>' +
          '<span class="iuFeedNewsSplit__capsule">AKTUÁLNÍ ČLÁNKY OVĚŘENÝCH MÉDIÍ</span>' +
          '<span class="iuFeedNewsSplit__line" aria-hidden="true"></span>' +
          "</div>";
        welcome.insertBefore(split, tall);
      }
      const mountSpecs = [
        ["iuNewsPreviewCardMount", "iuNewsPreviewCardMount", "data-iu-news-preview-mount"],
        ["iuSportPreviewCardMount", "iuSportPreviewCardMount", "data-iu-sport-preview-mount"],
        ["iuFinancePreviewCardMount", "iuFinancePreviewCardMount", "data-iu-finance-preview-mount"],
        ["iuHealthPreviewCardMount", "iuHealthPreviewCardMount", "data-iu-health-preview-mount"],
        ["iuTravelPreviewCardMount", "iuTravelPreviewCardMount", "data-iu-travel-preview-mount"],
        ["iuGamesPreviewCardMount", "iuGamesPreviewCardMount", "data-iu-games-preview-mount"],
        ["iuCulturePreviewCardMount", "iuCulturePreviewCardMount", "data-iu-culture-preview-mount"],
        ["iuScienceHistoryPreviewCardMount", "iuScienceHistoryPreviewCardMount", "data-iu-science-history-preview-mount"],
        ["iuEducationPreviewCardMount", "iuEducationPreviewCardMount", "data-iu-education-preview-mount"],
        ["iuPrehledDnePreviewCardMount", "iuPrehledDnePreviewCardMount", "data-iu-prehled-dne-preview-mount"],
      ];
      const root = document.getElementById("iuPrehledDneRoot");
      let insertAfter = root;
      for (let i = 0; i < mountSpecs.length; i++) {
        const id = mountSpecs[i][0];
        const cls = mountSpecs[i][1];
        const attr = mountSpecs[i][2];
        let el = document.getElementById(id);
        if (!el) {
          el = document.createElement("div");
          el.id = id;
          el.className = cls;
          el.setAttribute(attr, "");
          if (insertAfter && insertAfter.parentNode === viewport) {
            if (insertAfter.nextSibling) viewport.insertBefore(el, insertAfter.nextSibling);
            else viewport.appendChild(el);
          } else {
            viewport.appendChild(el);
          }
        }
        insertAfter = el;
      }
      if (!document.getElementById("iuFeedNewsSplitPostHomeCards")) {
        const post = document.createElement("div");
        post.id = "iuFeedNewsSplitPostHomeCards";
        post.className = "iuFeedNewsSplit iuFeedNewsSplit--postHomeCards";
        post.setAttribute("aria-hidden", "true");
        post.innerHTML =
          '<div class="iuFeedNewsSplit__row">' +
          '<span class="iuFeedNewsSplit__line" aria-hidden="true"></span>' +
          '<span class="iuFeedNewsSplit__capsule">DALŠÍ UŽITEČNÝ OBSAH</span>' +
          '<span class="iuFeedNewsSplit__line" aria-hidden="true"></span>' +
          "</div>";
        if (insertAfter && insertAfter.nextSibling) viewport.insertBefore(post, insertAfter.nextSibling);
        else viewport.appendChild(post);
        insertAfter = post;
      }
      if (!document.getElementById("iuSilverFinanceHomeCard")) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.id = "iuSilverFinanceHomeCard";
        btn.className = "iuSilverFinanceHomeCard";
        btn.setAttribute("data-iuq", "fincalc");
        btn.setAttribute("data-iu-silver-finance-home-card", "1");
        btn.setAttribute("aria-label", "Osobní finance a kalkulačky");
        btn.innerHTML =
          '<span class="iuSilverFinanceHomeCard__hero"><span class="iuSilverFinanceHomeCard__content">' +
          '<span class="iuSilverFinanceHomeCard__titleRow"><span class="iuSilverFinanceHomeCard__title">💰 Osobní finance a kalkulačky</span></span>' +
          '<span class="iuSilverFinanceHomeCard__lead">Máte své finance pod kontrolou? Získejte rychlý přehled o rozpočtu domácnosti, hypotéce a možnostech refinancování, investicích i spoření.</span>' +
          "</span></span>";
        if (insertAfter && insertAfter.nextSibling) viewport.insertBefore(btn, insertAfter.nextSibling);
        else viewport.appendChild(btn);
      }
    } catch (_) {}
  }

  function iuDesktopHomeCardsOrderNormalize(raw){
    try {
      const allowed = new Set(IU_HOME_CARDS_ORDER_DEFAULT);
      const out = [];
      const seen = new Set();
      const src = Array.isArray(raw) ? raw : [];
      for (let i = 0; i < src.length; i++) {
        const k = String(src[i] || "").trim().toLowerCase();
        if (!k || !allowed.has(k) || seen.has(k)) continue;
        seen.add(k);
        out.push(k);
      }
      for (let j = 0; j < IU_HOME_CARDS_ORDER_DEFAULT.length; j++) {
        const dk = IU_HOME_CARDS_ORDER_DEFAULT[j];
        if (!seen.has(dk)) out.push(dk);
      }
      return out;
    } catch (_) {
      return IU_HOME_CARDS_ORDER_DEFAULT.slice();
    }
  }

  function iuDesktopHomeCardsOrderLoad(){
    try {
      const raw = localStorage.getItem(IU_HOME_CARDS_ORDER_KEY);
      if (!raw) return IU_HOME_CARDS_ORDER_DEFAULT.slice();
      return iuDesktopHomeCardsOrderNormalize(JSON.parse(raw));
    } catch (_) {
      return IU_HOME_CARDS_ORDER_DEFAULT.slice();
    }
  }

  function iuDesktopHomeCardsOrderSave(order){
    try {
      const norm = iuDesktopHomeCardsOrderNormalize(order);
      localStorage.setItem(IU_HOME_CARDS_ORDER_KEY, JSON.stringify(norm));
      return norm;
    } catch (_) {
      return IU_HOME_CARDS_ORDER_DEFAULT.slice();
    }
  }

  function iuDesktopHomeCardsOrderApply(){
    try {
      if (!iuIsDesktopNavLayout()) return;
      const viewport = document.getElementById("iuSilverTallScrollViewport");
      if (!viewport) return;
      const order = iuDesktopHomeCardsOrderLoad();
      const anchor = viewport.querySelector("[data-iu-silver-tall-scroll-placeholder]");
      for (let i = 0; i < order.length; i++) {
        const mountId = IU_HOME_CARD_MOUNT_BY_KEY[order[i]];
        if (!mountId) continue;
        const mount = document.getElementById(mountId);
        if (!mount || !mount.parentNode) continue;
        if (anchor && anchor.parentNode === viewport) {
          viewport.insertBefore(mount, anchor);
        } else {
          viewport.appendChild(mount);
        }
      }
    } catch (_) {}
  }

  function iuDesktopHomeCardsDragInit(){
    try {
      if (!iuLegacyHomeCardsWanted()) return;
      if (window.__iuDesktopHomeCardsDragInit) return;
      window.__iuDesktopHomeCardsDragInit = 1;
    } catch (_) {}
    try {
      window.iuDesktopHomeCardsOrderApply = iuDesktopHomeCardsOrderApply;
    } catch (_) {}
    iuDesktopHomeCardsOrderApply();
    const viewport = document.getElementById("iuSilverTallScrollViewport");
    if (!viewport) return;
    let dragSrc = null;
    let dragDidMove = false;
    viewport.addEventListener(
      "dragstart",
      function (e) {
        try {
          if (!iuIsDesktopNavLayout()) return;
          if (!document.body.classList.contains("iu-desktop-home-grid")) return;
          const mount = e.target && e.target.closest ? e.target.closest('[class$="PreviewCardMount"]') : null;
          if (!mount || mount.parentNode !== viewport) return;
          dragSrc = mount;
          dragDidMove = false;
          mount.classList.add("iu-homecard-dragging");
          try {
            if (e.dataTransfer) {
              e.dataTransfer.effectAllowed = "move";
              e.dataTransfer.setData("text/plain", mount.id || "");
            }
          } catch (_) {}
        } catch (_) {}
      },
      true
    );
    viewport.addEventListener(
      "dragover",
      function (e) {
        try {
          if (!dragSrc) return;
          e.preventDefault();
          const over = e.target && e.target.closest ? e.target.closest('[class$="PreviewCardMount"]') : null;
          viewport.querySelectorAll('[class$="PreviewCardMount"].iu-homecard-drag-over').forEach(function (el) {
            el.classList.remove("iu-homecard-drag-over");
          });
          if (over && over !== dragSrc && over.parentNode === viewport) {
            over.classList.add("iu-homecard-drag-over");
            const rect = over.getBoundingClientRect();
            const before = e.clientY < rect.top + rect.height / 2;
            if (before) viewport.insertBefore(dragSrc, over);
            else viewport.insertBefore(dragSrc, over.nextSibling);
            dragDidMove = true;
          }
        } catch (_) {}
      },
      true
    );
    viewport.addEventListener(
      "dragend",
      function () {
        try {
          if (dragSrc) dragSrc.classList.remove("iu-homecard-dragging");
          viewport.querySelectorAll('[class$="PreviewCardMount"].iu-homecard-drag-over').forEach(function (el) {
            el.classList.remove("iu-homecard-drag-over");
          });
          if (dragSrc && dragDidMove) {
            const mounts = viewport.querySelectorAll('[class$="PreviewCardMount"]');
            const nextOrder = [];
            mounts.forEach(function (m) {
              const id = String(m.id || "");
              for (const key in IU_HOME_CARD_MOUNT_BY_KEY) {
                if (IU_HOME_CARD_MOUNT_BY_KEY[key] === id) {
                  nextOrder.push(key);
                  break;
                }
              }
            });
            iuDesktopHomeCardsOrderSave(nextOrder);
          }
        } catch (_) {}
        dragSrc = null;
        dragDidMove = false;
      },
      true
    );
    try {
      const mounts = viewport.querySelectorAll('[class$="PreviewCardMount"]');
      mounts.forEach(function (mount) {
        try {
          mount.setAttribute("draggable", "true");
        } catch (_) {}
      });
    } catch (_) {}
    try {
      const mq = window.matchMedia && window.matchMedia("(min-width: 1025px)");
      const reapply = function () {
        try {
          iuDesktopHomeCardsOrderApply();
          const m = viewport.querySelectorAll('[class$="PreviewCardMount"]');
          m.forEach(function (mount) {
            try {
              if (document.body.classList.contains("iu-desktop-home-grid")) {
                mount.setAttribute("draggable", "true");
              } else {
                mount.removeAttribute("draggable");
              }
            } catch (_) {}
          });
        } catch (_) {}
      };
      if (mq && mq.addEventListener) mq.addEventListener("change", reapply);
      else if (mq && mq.addListener) mq.addListener(reapply);
    } catch (_) {}
  }

  /** P0 desktop-only (≥1025px + /projects/ hub): body.iu-desktop-home-grid — 2-column section tiles; mobile/tablet unchanged. */
  function iuDesktopHomeCardsEnsureDomAll() {
    try {
      if (!iuLegacyHomeCardsWanted()) return;
      if (!document.body || !document.body.classList.contains("iu-desktop-home-grid")) return;
      try { iuLegacyHomeCardsEnsureShell(); } catch (_) {}
      try { iuNewsPreviewEnsureDom(); } catch (_) {}
      try { iuSportPreviewEnsureDom(); } catch (_) {}
      try { iuFinancePreviewEnsureDom(); } catch (_) {}
      try { iuHealthPreviewEnsureDom(); } catch (_) {}
      try { iuTravelPreviewEnsureDom(); } catch (_) {}
      try { iuGamesPreviewEnsureDom(); } catch (_) {}
      try { iuCulturePreviewEnsureDom(); } catch (_) {}
      try { iuScienceHistoryPreviewEnsureDom(); } catch (_) {}
      try { iuEducationPreviewEnsureDom(); } catch (_) {}
      try { iuPrehledDnePreviewEnsureDom(); } catch (_) {}
      try {
        if (typeof state !== "undefined" && state && state.hasLoadedData) {
          iuSilverTallMediaPreviewsRefresh();
        }
      } catch (_) {}
    } catch (_) {}
  }

  function iuDesktopInitialScrollTopApply() {
    try {
      if (!iuIsDesktopNavLayout()) return;
      const p = new URLSearchParams(String(location.search || ""));
      if (String(p.get("section") || "").trim()) return;
      try {
        sessionStorage.removeItem("iu:lastScrollY");
      } catch (_) {}
      try {
        const raw = sessionStorage.getItem("iu:scrollRestoreMapV1");
        const m = raw ? JSON.parse(raw) : {};
        if (m && typeof m === "object") {
          delete m.home;
          sessionStorage.setItem("iu:scrollRestoreMapV1", JSON.stringify(m));
        }
      } catch (_) {}
      window.scrollTo(0, 0);
      const se = document.scrollingElement || document.documentElement;
      if (se) se.scrollTop = 0;
      if (document.body) document.body.scrollTop = 0;
    } catch (_) {}
  }

  try { window.iuDesktopInitialScrollTopApply = iuDesktopInitialScrollTopApply; } catch (_) {}

  function iuDesktopHomeSectionTopGapSync(){
    try{
      const stage = document.getElementById("iuCenterStage");
      const body = document.body;
      if (!stage) return;
      if (!body || !body.classList.contains("iu-desktop-home-grid") || !iuIsDesktopNavLayout()) {
        if (body) {
          body.style.removeProperty("--iu-dhp-center-stage-mt");
          body.removeAttribute("data-iu-gap-synced");
        }
        return;
      }
      const homecards = document.getElementById("iuSilverTallScrollSection");
      const stack = document.getElementById("iuSilverTopCardsStack");
      if (!homecards || !stack) return;
      const stackTop = stack.getBoundingClientRect().top;
      const hcBottom = homecards.getBoundingClientRect().bottom;
      const stackMt = parseFloat(getComputedStyle(stack).marginTop) || 0;
      const gridCellTop = stackTop - stackMt;
      const margin = Math.max(20, Math.round(hcBottom - gridCellTop + 20));
      body.style.setProperty("--iu-dhp-center-stage-mt", margin + "px");
      body.setAttribute("data-iu-gap-synced", "1");
    }catch(_){}
  }
  function iuDesktopHomeSectionGridGuardApply(){
    try{
      const body = document.body;
      if (!body) return;
      const vp = document.getElementById("iuSilverTallScrollViewport");
      if (!vp) {
        body.classList.remove("iu-desktop-home-grid");
        try{ iuDesktopHomeSectionTopGapSync(); }catch(_){}
        return;
      }
      const hub = typeof iuIsProjectsRoute === "function" ? iuIsProjectsRoute() : false;
      const mq = typeof window.matchMedia === "function" ? window.matchMedia("(min-width: 1025px)") : null;
      const ok = !!(hub && mq && mq.matches);
      if (ok) body.classList.add("iu-desktop-home-grid");
      else body.classList.remove("iu-desktop-home-grid");
      try {
        if (iuLegacyHomeCardsWanted()) iuLegacyHomeCardsEnsureShell();
      } catch (_) {}
      if (ok) {
        try { iuDesktopHomeCardsEnsureDomAll(); } catch (_) {}
        try { iuDesktopInitialScrollTopApply(); } catch (_) {}
        try { iuArticleActionsEnsureDesktopButton(); } catch (_) {}
      }
      try{ iuDesktopHomeSectionTopGapSync(); }catch(_){}
    }catch(_){}
  }
  function iuDesktopHomeSectionGridGuardInit(){
    try{
      if (window.__iuDesktopHomeSectionGridGuardInit) return;
      window.__iuDesktopHomeSectionGridGuardInit = 1;
    }catch{}
    try{
      window.iuDesktopHomeSectionGridGuardApply = iuDesktopHomeSectionGridGuardApply;
      window.iuDesktopHomeSectionTopGapSync = iuDesktopHomeSectionTopGapSync;
    }catch{}
    iuDesktopHomeSectionGridGuardApply();
    try { iuDesktopInitialScrollTopApply(); } catch (_) {}
    try{
      const mq = window.matchMedia && window.matchMedia("(min-width: 1025px)");
      if (mq && mq.addEventListener) mq.addEventListener("change", iuDesktopHomeSectionGridGuardApply);
      else if (mq && mq.addListener) mq.addListener(iuDesktopHomeSectionGridGuardApply);
    }catch{}
    try{
      window.addEventListener("resize", iuDesktopHomeSectionTopGapSync, { passive: true });
    }catch{}
    try{
      const gapTargets = [
        document.getElementById("iuSilverTallScrollSection"),
        document.getElementById("iuDesktopInfoPanelMount"),
        document.getElementById("iuSilverTopCardsStack"),
      ].filter(Boolean);
      if (gapTargets.length && typeof ResizeObserver === "function") {
        const ro = new ResizeObserver(function () {
          try{ iuDesktopHomeSectionTopGapSync(); }catch(_){}
        });
        gapTargets.forEach(function (el) { ro.observe(el); });
      }
    }catch(_){}
    try{ iuDesktopHomeCardsDragInit(); }catch(_){}
  }

  /** P0 CLS: desktop grid ukazuje jen 1 headline — neplnit druhý řádek textem (jinak layout 2 titulků → skrytí sníží výšku dlaždice a naměří se CLS). */
  function iuDesktopHomeGridOmitSecondaryHeadline(){
    try{
      if (typeof document === "undefined" || !document.body) return false;
      if (!document.body.classList.contains("iu-desktop-home-grid")) return false;
      return !!(typeof window.matchMedia === "function" && window.matchMedia("(min-width: 1025px)").matches);
    }catch(_){
      return false;
    }
  }

  function iuNewsPreviewHideTallScrollPlaceholder(viewport){
    try{
      if (!viewport) return;
      const placeholder = viewport.querySelector("[data-iu-silver-tall-scroll-placeholder]");
      if (placeholder) {
        try {
          placeholder.style.visibility = "hidden";
          placeholder.setAttribute("aria-hidden", "true");
        } catch (_) {}
      }
      const probe = viewport.querySelector("[data-iu-silver-tall-scroll-probe]");
      if (probe) {
        try {
          probe.style.visibility = "hidden";
          probe.setAttribute("aria-hidden", "true");
        } catch (_) {}
      }
    }catch(_){}
  }

  function iuNewsPreviewWireCard(card){
    try{
      if (!card || card.getAttribute("data-iu-news-preview-iu-bound") === "1") return;
      card.setAttribute("data-iu-news-preview-iu-bound", "1");
      card.addEventListener(
        "click",
        function () {
          iuMediaPreviewNavClick("zpravy");
        },
        { passive: true }
      );
      const img0 = card.querySelector(".iuNewsPreviewImg");
      if (img0 && !img0.getAttribute("data-iu-news-preview-err-bound")) {
        img0.setAttribute("data-iu-news-preview-err-bound", "1");
        img0.onerror = function () {
          const fb = "/assets/images/news-default.jpg";
          try {
            const cur = String(img0.getAttribute("src") || "");
            if (cur.indexOf("news-default.jpg") !== -1) {
              img0.onerror = null;
              return;
            }
          } catch (_) {}
          img0.src = fb;
        };
      }
    }catch(_){}
  }

  function iuNewsPreviewEnsureDom(){
    try{
      if (!iuLegacyHomeCardsWanted()) return null;
      try { iuLegacyHomeCardsEnsureShell(); } catch (_) {}
      const viewport = document.getElementById("iuSilverTallScrollViewport");
      if (!viewport) return null;
      const mount = document.getElementById("iuNewsPreviewCardMount");
      let card = mount
        ? mount.querySelector('[data-iu-news-preview-card="1"]')
        : viewport.querySelector('[data-iu-news-preview-card="1"]');
      if (card) {
        iuNewsPreviewHideTallScrollPlaceholder(viewport);
        iuNewsPreviewWireCard(card);
        return card;
      }

      card = document.createElement("button");
      card.type = "button";
      card.className = "iuNewsPreviewCard";
      card.setAttribute("data-iu-news-preview-card", "1");
      card.setAttribute("aria-label", "Otevřít sekci Zprávy");

      card.innerHTML = `
        <div class="iuNewsPreviewHeader" data-iu-news-preview-header>
          <div class="iuNewsPreviewTitleRow">
            <span class="iuNewsPreviewBadge" data-iu-news-preview-badge>Zprávy</span>
            <span class="iuNewsPreviewFreshness" data-iu-news-preview-freshness></span>
          </div>
          <svg class="iuNewsPreviewChevron" viewBox="0 0 20 20" aria-hidden="true" focusable="false">
            <path d="M7.5 4.5l5 5-5 5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="iuNewsPreviewBody">
          <div class="iuNewsPreviewImgWrap" aria-hidden="true">
            <img class="iuNewsPreviewImg" data-iu-defer-src="/assets/images/news-default.jpg" width="112" height="84" loading="lazy" decoding="async" alt="" />
          </div>
          <div class="iuNewsPreviewText">
            <p class="iuNewsPreviewHeadline" data-iu-news-preview-title-1>Zprávy se načítají</p>
            <p class="iuNewsPreviewHeadline2 iuNewsPreviewHeadline2--empty" data-iu-news-preview-title-2></p>
          </div>
        </div>
      `.trim();

      iuNewsPreviewHideTallScrollPlaceholder(viewport);

      if (mount) {
        mount.appendChild(card);
      } else {
        viewport.insertBefore(card, viewport.firstChild || null);
      }

      iuNewsPreviewWireCard(card);

      return card;
    }catch(_){
      return null;
    }
  }

  function iuNewsPreviewRefresh(){
    try{
      const card = iuNewsPreviewEnsureDom();
      if (!card) return;
      const badge = card.querySelector("[data-iu-news-preview-badge]");
      const elFresh = card.querySelector("[data-iu-news-preview-freshness]");
      const elT1 = card.querySelector("[data-iu-news-preview-title-1]");
      const elT2 = card.querySelector("[data-iu-news-preview-title-2]");
      const elImg = card.querySelector(".iuNewsPreviewImg");
      if (!elT1 || !elT2 || !elFresh) return;

      const fallbackThumb = "/assets/images/news-default.jpg";
      const picked = iuNewsPreviewPickLatestTwoFromState();
      const latest = picked.latest;
      const second = picked.second;
      const latestTitle = latest && latest.title ? String(latest.title) : "";
      const secondTitle = second && second.title ? String(second.title) : "";
      const hasLatest = !!latestTitle;

      if (
        iuTallPreviewHoldStableWhenTransientEmpty(
          card,
          elT1,
          hasLatest,
          "data-iu-news-preview-has-latest",
          "Zprávy se načítají",
        )
      ) {
        return;
      }

      // DATA GUARD markers (testable / proof hooks)
      if (hasLatest) {
        card.setAttribute("data-iu-news-preview-has-latest", "1");
        card.setAttribute("data-iu-news-preview-latest-title", latestTitle);
      } else {
        card.setAttribute("data-iu-news-preview-has-latest", "0");
        card.removeAttribute("data-iu-news-preview-latest-title");
      }
      if (secondTitle && !iuDesktopHomeGridOmitSecondaryHeadline()) card.setAttribute("data-iu-news-preview-second-title", secondTitle);
      else card.removeAttribute("data-iu-news-preview-second-title");

      if (!hasLatest) {
        if (badge) {
          try {
            badge.textContent = "Zprávy";
          } catch (_) {}
        }
        elFresh.textContent = "";
        elFresh.setAttribute("data-iu-news-preview-has-freshness", "0");
        card.removeAttribute("data-iu-news-preview-latest-ms");
        card.removeAttribute("data-iu-news-preview-published-raw");
        elT1.textContent = "Zprávy se načítají";
        elT2.textContent = "";
        try { elT2.classList.add("iuNewsPreviewHeadline2--empty"); } catch (_) {}
        try {
          iuPreviewImgApplyThumb(elImg, fallbackThumb);
        } catch (_) {}
        return;
      }

      // Titles
      elT1.textContent = latestTitle;
      if (iuDesktopHomeGridOmitSecondaryHeadline()) {
        elT2.textContent = "";
        try { elT2.classList.add("iuNewsPreviewHeadline2--empty"); } catch (_) {}
      } else if (secondTitle) {
        elT2.textContent = secondTitle;
        try { elT2.classList.remove("iuNewsPreviewHeadline2--empty"); } catch (_) {}
      } else {
        elT2.textContent = "";
        try { elT2.classList.add("iuNewsPreviewHeadline2--empty"); } catch (_) {}
      }
      try {
        if (
          typeof window !== "undefined" &&
          window.__IU_PREVIEW_FEED_PROBE__ === true &&
          latestTitle &&
          !window.__iuPreviewFeedProbe?._zpravyDomLogged
        ) {
          window.__iuPreviewFeedProbe = window.__iuPreviewFeedProbe || {};
          window.__iuPreviewFeedProbe._zpravyDomLogged = true;
          iuPreviewFeedProbeTick("zpravyPreviewDomPatched", {
            second: Boolean(secondTitle && !iuDesktopHomeGridOmitSecondaryHeadline()),
          });
        }
      } catch (_) {}

      // Freshness + badge (NO fake: only if we have valid timestamp)
      const publishedRaw = iuNewsPreviewPublishedRaw(latest);
      const ms = picked.latestMs;
      const fresh = iuCsRelativeFreshnessFromMs(ms, Date.now());
      if (fresh) {
        elFresh.textContent = fresh;
        elFresh.setAttribute("data-iu-news-preview-has-freshness", "1");
        card.setAttribute("data-iu-news-preview-latest-ms", String(ms));
        if (publishedRaw) card.setAttribute("data-iu-news-preview-published-raw", publishedRaw);
        else card.removeAttribute("data-iu-news-preview-published-raw");
      } else {
        elFresh.textContent = "";
        elFresh.setAttribute("data-iu-news-preview-has-freshness", "0");
        card.removeAttribute("data-iu-news-preview-latest-ms");
        card.removeAttribute("data-iu-news-preview-published-raw");
      }
      if (badge) {
        try {
          badge.textContent = "Zprávy";
        } catch (_) {}
      }

      try {
        if (elImg) {
          const rawIm = latest && latest.image !== undefined && latest.image !== null ? latest.image : "";
          const thumbSrc = iuNewsPreviewIsValidImage(rawIm) ? String(rawIm).trim() : fallbackThumb;
          iuPreviewImgApplyThumb(elImg, thumbSrc);
        }
      } catch (_) {}
    }catch(_){}
  }

