  function iuWeatherIsValidGeoCoords(lat, lon){
    const la = Number(lat);
    const lo = Number(lon);
    return (
      Number.isFinite(la) &&
      Number.isFinite(lo) &&
      la >= -90 &&
      la <= 90 &&
      lo >= -180 &&
      lo <= 180
    );
  }

